22	 * 目标语言在 document 表中以逗号分隔存储，行记录中还原为列表。
23	 */
24	@Repository
25	public class TranslationRepository {
26	
27	    private static final RowMapper<DocumentRow> DOCUMENT_MAPPER = (rs, n) -> new DocumentRow(
28	            rs.getLong("document_id"),
29	            Arrays.stream(rs.getString("target_languages").split(",")).toList(),
30	            rs.getInt("draft_version"),
31	            rs.getInt("published_version"),
32	            rs.getInt("term_version"));
33	
