38	            rs.getString("segment_id"), rs.getString("language"), rs.getString("content"),
39	            rs.getString("author"), rs.getInt("source_version"), rs.getInt("translation_version"),
40	            rs.getInt("term_version"));
41	
42	    private static final RowMapper<ApprovalRow> APPROVAL_MAPPER = (rs, n) -> new ApprovalRow(
43	            rs.getString("segment_id"), rs.getString("language"), rs.getString("reviewer"),
44	            rs.getInt("source_version"), rs.getInt("translation_version"));
45	
46	    private static final RowMapper<TermRuleRow> TERM_RULE_MAPPER = (rs, n) -> new TermRuleRow(
47	            rs.getString("source_term"), rs.getString("language"), rs.getString("required_translation"));
48	
49	    private final JdbcTemplate jdbc;
50	
51	    public TranslationRepository(JdbcTemplate jdbc) {
52	        this.jdbc = jdbc;
53	    }
54	
55	    /** 插入文档并返回自增 ID，初始草稿版本 1、发布版本 0、术语版本 0。 */
56	    public long insertDocument(List<String> targetLanguages) {
57	        KeyHolder keyHolder = new GeneratedKeyHolder();
58	        jdbc.update(con -> {
59	            PreparedStatement ps = con.prepareStatement(
60	                    "INSERT INTO document (target_languages, draft_version, published_version, term_version) "
61	                            + "VALUES (?, 1, 0, 0)",
62	                    new String[]{"document_id"});
63	            ps.setString(1, String.join(",", targetLanguages));
64	            return ps;
65	        }, keyHolder);
66	        Number key = keyHolder.getKey();
67	        if (key == null) {
68	            throw new IllegalStateException("文档创建后未返回自增主键");
69	        }
70	        return key.longValue();
71	    }
72	
73	    /** 按 ID 查询文档并加行级写锁（FOR UPDATE），用于串行化同一文档的写操作。 */
74	    public Optional<DocumentRow> findDocumentForUpdate(long documentId) {
75	        List<DocumentRow> rows = jdbc.query(
76	                "SELECT document_id, target_languages, draft_version, published_version, term_version "
77	                        + "FROM document WHERE document_id = ? FOR UPDATE",
78	                DOCUMENT_MAPPER, documentId);
79	        return rows.stream().findFirst();
80	    }
81	
82	    /** 只读查询文档（不加锁），用于快照查询。 */
83	    public Optional<DocumentRow> findDocument(long documentId) {
84	        List<DocumentRow> rows = jdbc.query(
85	                "SELECT document_id, target_languages, draft_version, published_version, term_version "
