public ApiDtos.LegalSignoffResponse submitLegalSignoff(long documentId, String segmentId, String language,
                                                       String actorId, ApiDtos.LegalSignoffRequest request) {
    lockDocument(documentId);
    String normalizedLanguage = normalizeLanguage(language);
    SegmentRow segment = findSegmentOrThrow(documentId, segmentId);
    TranslationRow translation = repository.findTranslation(documentId, segmentId, normalizedLanguage)
            .orElseThrow(() -> ApiException.notFound("译文不存在: ..."));
    if (translation.translationVersion() != request.expectedVersion()) {
        throw ApiException.conflict("译文版本冲突：当前译文版本 X，与期望的 Y 不一致");
    }
    // 须为已批准译文：批准须匹配当前源文与译文版本
    ApprovalRow approval = repository.findApproval(...).orElseThrow(() -> ApiException.unprocessable("译文尚未批准，不能审签"));
    if (approval.translationVersion() != translation.translationVersion() || approval.sourceVersion() != segment.sourceVersion()) {
        throw ApiException.unprocessable("批准已失效，需重新批准后再审签");
    }
    String status = request.status();  // validated by @Pattern
    String reason = request.reason();
    if ("REJECTED".equals(status) && (reason == null || reason.isBlank())) {
        throw ApiException.unprocessable("拒绝说明不能为空");
    }
    repository.upsertLegalSignoff(documentId, new LegalSignoffRow(segmentId, normalizedLanguage, actorId,
            translation.translationVersion(), status, reason, null));
    return new ApiDtos.LegalSignoffResponse(...);
}
